contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send `amount` wei to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has the funds to send if it will send
        require(address(this).balance >= amount);

        // observe before-values
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;

        // GENERAL RULE:
        // For any input amount, either the call reverted or the pot after the call is
        // either unchanged/increased (afterPot >= beforePot) or exactly zero (payout case).
        // Thus pot never decreases to a non-zero smaller value.
        assert(reverted || (afterPot >= beforePot) || (afterPot == 0));
    }

    // accept Ether so this contract can fund calls
    receive() external payable {}
}

